  ['description', '-', 'purpose'] =>
    '要確認: wellbeing→「ウェルビーイング」（他候補: 健康と幸福、安寧）、healthcare professional→「医療従事者」（healthcare provider と同じ訳）、carer→「介護者」',
  ['description', '-', 'use'] =>
    'condition→「病態」、Problem List→「問題リスト」、Discharge Summary→「退院時サマリー」、clinical consultation→「診察」（紹介の consultation＝コンサルテーションとは区別）、clinical decision support→「臨床意思決定支援」',
  ['description', '-', 'misuse'] =>
    'Presenting Complaint→「主訴」、examination findings→「診察所見」、laboratory test results→「臨床検査結果」、imaging→「画像検査／画像診断」、procedure→「処置」、exclusion→「除外」',
  ['description', '-', 'keywords'] =>
    '原文7語（issue→課題、condition→病態、problem→問題、diagnosis→診断、concern→懸念、injury→外傷、clinical impression→臨床的印象）に「傷病名」「病名」を追加（CKM 検索性のため）'
}.freeze

src, dst = ARGV
lines = File.readlines(src, chomp: true)
out = [lines.shift]
lines.each do |l|
  c = l.split("\t", -1)
  key = c[1..3]
  c[6] = T.fetch(key).gsub("\n", '\n')
  c[7] = NOTES[key] || ''
  out << c.join("\t")
end
File.write(dst, out.join("\n") + "\n")
